     */
    val channelMask: Int,
    /**
     * The subset of `channel_mask` with inverted polarity.
     */
    val invertMask: Int,
    /**
     * `SIGGEN_FLAG_*`.
     */
    val flags: Int,
    /**
     * Peak level, dBFS, -120..0.
     */
    val levelDb: Float,
    /**
     * Duration, ms.
     */
    val durationMs: Long,
    /**
     * Repeat count.
     */
    val repeat: Int,
    /**
     * Gap between repeats, ms.
     */
    val gapMs: Int,
    /**
     * Type-specific parameters, exactly 4.
     */
    val p: List<Float>,
)

/**
 * What the generator is doing (`siggen_get_status`).
 */
data class SiggenStatus(
    /**
     * `SIGGEN_STATE_*`: idle, fade in, run, gap, fade out.
     */
    val state: Int,
    /**
     * The active or last `SIGGEN_TYPE_*`.
     */
    val signalType: Int,
    /**
     * The walked output; 0xFF when not walking.
     */
    val activeChannel: Int,
    /**
     * Time since start, ms.
     */
    val elapsedMs: Long,
    /**
     * Completed sweeps or pattern periods.
     */
    val cyclesDone: Int,
    /**
     * `SIGGEN_STOP_*` of the last stop.
     */
    val stopReason: Int,
    /**
     * Instantaneous sweep frequency, Hz; 0 when not sweeping.
     */
    val currentFreq: Float,
)

/**
 * One parameter of a signal type.
 */
data class SiggenParam(
    /**
     * `SIGGEN_PARAM_*`: what the value means (0 = unused).
     */
    val semantic: Int,
    /**
     * Lowest value.
     */
    val min: Float,
    /**
     * Highest value.
     */
    val max: Float,
    /**
     * Default value.
     */
    val def: Float,
)

/**
 * One signal type the generator offers.
 */
data class SiggenTypeInfo(
    /**
     * `SIGGEN_TYPE_*`; 0xFF when its descriptor could not be read.
     */
    val id: Int,
    /**
     * Display name.
     */
    val name: String,
    /**
     * `SIGGEN_TIMING_*`: continuous, sweep or pattern.
     */
    val timing: Int,
    /**
     * Exactly 4.
     */
    val params: List<SiggenParam>,
)

/**
 * The generator's capabilities (`siggen_fetch_caps`).
 */
data class SiggenCaps(
    /**
     * The firmware has a generator.
     */
    val supported: Boolean,
    /**
     * Signal types it reports.
     */
    val typeCount: Int,
    /**
     * Output channels it can drive.
     */
    val outputChannels: Int,
    /**
     * Most tones of a multitone signal.
     */
    val multitoneMax: Int,
    /**
     * Bit per channel: valid in `SiggenConfig.channel_mask`.
     */
    val validMask: Int,
    /**
     * SIGGEN_TYPE_COUNT = 15 entries; first `type_count` valid.
     */
    val types: List<SiggenTypeInfo>,
)

/**
 * One S/PDIF output's buffers.
 */
data class SpdifBufferStats(
    /**
     * Free ring space, 48-frame buckets, 0..16.
     */
    val free: Int,
    /**
     * Ring fill, 48-frame buckets, 0..16.
     */
    val prepared: Int,
    /**
     * DMA buffers in flight, 0..1.
     */
    val playing: Int,
    /**
     * Consumer pipeline fill, %.
     */
    val fillPct: Int,
    /**
     * Lowest fill since the last reset, %.
     */
    val minPct: Int,
    /**
     * Highest fill since the last reset, %.
     */
    val maxPct: Int,
)

/**
 * The PDM output's buffers.
 */
data class PdmBufferStats(
    /**
     * DMA buffer fill, %.
     */
    val dmaFillPct: Int,
    /**
     * Lowest DMA fill since the last reset, %.
     */
    val dmaMinPct: Int,
    /**
     * Highest DMA fill since the last reset, %.
     */
    val dmaMaxPct: Int,
    /**
     * Software ring fill, %.
     */
    val ringFillPct: Int,
    /**
     * Lowest ring fill since the last reset, %.
     */
    val ringMinPct: Int,
    /**
     * Highest ring fill since the last reset, %.
     */
    val ringMaxPct: Int,
)

/**
 * Buffer fill levels and watermarks (`fetch_buffer_stats`).
 */
data class BufferStats(
    /**
     * Live entries of `spdif`, at most 4.
     */
    val numSpdif: Int,
    /**
     * The PDM output is active.
     */
    val pdmActive: Boolean,
    /**
     * Audio is streaming.
     */
    val streaming: Boolean,
    /**
     * Monotonic counter, wrapping.
     */
    val sequence: Int,
    /**
     * Exactly 4.
     */
    val spdif: List<SpdifBufferStats>,
    /**
     * The PDM output.
     */
    val pdm: PdmBufferStats,
)

/**
 * The S/PDIF receiver (`fetch_spdif_rx_status`).
 */
data class SpdifRxStatus(
    /**
     * 0 inactive, 1 acquiring, 2 locked, 3 relocking.
     */
    val state: Int,
    /**
     * The input source, raw `InputSource`.
     */
    val inputSource: Int,
    /**
     * Times it locked.
     */
    val lockCount: Int,
    /**
     * Times it lost lock.
     */
    val lossCount: Int,
    /**
     * Sample rate when locked, Hz.
     */
    val sampleRate: Long,
    /**
     * Parity errors counted.
     */
    val parityErrors: Long,
    /**
     * Receive FIFO fill, %.
     */
    val fifoFillPct: Int,
    /**
     * The receiver library's debug state.
     */
    val libState: Int,
    /**
     * Stable callbacks, 4-bit counter.
     */
    val stableCallbacks: Int,
    /**
     * Lost callbacks, 4-bit counter.
     */
    val lostCallbacks: Int,
)

/**
 * One line of the notification monitor.
 */
data class MonitorEntry(
    /**
     * Rising id, for `monitor_read`.
     */
    val id: Long,
    /**
     * Host time, ms since the Unix epoch.
     */
    val timeMs: Long,
    /**
     * The entry, for display.
     */
    val text: String,
)

/**
 * Result of `monitor_read(after_id)`: the entries after `after_id` and the
 * id to pass next time (`after_id` itself if there were none).
 */
data class MonitorBatch(
    /**
     * The id to pass next time.
     */
    val lastId: Long,
    /**
     * Entries after `after_id`, oldest first.
     */
    val entries: List<MonitorEntry>,
)

/**
 * One GPIO held by a live control-surface binding (`dspi_cs_pin_uses`).
 */
data class PinUse(
    /**
     * The GPIO.
     */
    val pin: Int,
    /**
     * The binding's slot.
     */
    val slot: Int,
)

/**
 * `dspi_bootloader_counts`. Always 0/0 on Android (no bus to
 * enumerate from native code); Android uses the Kotlin BootloaderLocator instead.
 */
data class BootloaderCounts(
    /**
     * RP2040 boards in BOOTSEL mode.
     */
    val rp2040: Long,
    /**
     * RP2350 boards in BOOTSEL mode.
     */
    val rp2350: Long,
)

/**
 * Version facts of the linked core, for the About page and sanity checks.
 */
data class CoreInfo(
    /**
     * dspi-ffi crate version.
     */
    val ffiVersion: String,
    /**
     * `protocol::WIRE_FORMAT_VERSION` (32).
     */
    val wireFormatVersion: Int,
    /**
     * `protocol::MIN_WIRE_FORMAT_VERSION` (16).
     */
    val minWireFormatVersion: Int,
    /**
     * `protocol::BULK_PARAMS_SIZE` (6136).
     */
    val bulkParamsSize: Long,
    /**
     * Number of points in `compute_magnitude_curve` / `compute_phase_curve` (201).
     */
    val magnitudePoints: Long,
)

/**
 * The hub's `hello` after `link_connect` (spec 7.2).
 */
data class LinkHello(
    /**
     * `hid`: lowercase UUID, stable per hub installation. Tokens are keyed on it.
     */
    val hubId: String,
    /**
     * The hub's display name.
     */
    val hubName: String,
    /**
     * `console` (DSPi Console in gateway mode) or `bridge` (ESP32 on the UART).
     */
    val hubKind: String,
    /**
     * The hub's software version.
     */
    val hubVersion: String,
    /**
     * The Link protocol minor version it speaks.
     */
    val protoMinor: Long,
    /**
     * `none` or `pin`.
     */
    val auth: String,
    /**
     * `window` (PIN shown on the hub) or `fixed` (the hub's own PIN); `window` when absent.
     */
    val pinSource: String,
    /**
     * True: ask the user for the PIN and call `link_pair`.
     */
    val needsPairing: Boolean,
    /**
     * `cmd`, `notify`, `poll`, `snapshot`, `lock`, `fw_install`, `rename`, ...
     */
    val caps: List<String>,
    /**
     * Largest payload it takes, bytes.
     */
    val maxPayload: Long,
    /**
     * Requests it allows in flight.
     */
    val maxInflight: Long,
    /**
     * The hub refused the token passed in: forget it. Only this says the
     * token is bad; any other failure keeps it.
     */
    val tokenRefused: Boolean,
)

/**
 * One device the hub shares (`device.list`, spec 7.4).
 */
data class LinkDevice(
    /**
     * The hub's handle for it, for `link_select_device`.
     */
    val handle: Long,
    /**
     * USB serial number.
     */
    val serial: String,
    /**
     * The board's own name, else the hub's.
     */
    val name: String,
    /**
     * `major.minor.patch`, "" when the hub did not say.
     */
    val fw: String,
    /**
     * Beta number, 0 = final, -1 = unknown.
     */
    val fwBeta: Int,
    /**
     * 0 RP2040, 1 RP2350, -1 unknown.
     */
    val platform: Int,
    /**
     * `online`, `offline`, `updating`.
     */
    val state: String,
    /**
     * `usb` or `uart` (latency and bulk timing).
     */
    val link: String,
    /**
     * Session holding the device lock, 0 = none.
     */
    val lockedBy: Long,
)

/**
 * A `[bRequest, dir]` row of `policy.denied` (dir 0 = SET, 1 = GET).
 */
data class LinkDenied(
    /**
     * The `bRequest`.
     */
    val request: Int,
    /**
     * 0 = SET, 1 = GET.
     */
    val dir: Int,
)

/**
 * Where the current Link session stands.
 */
data class LinkStatus(
    /**
     * A session exists (connected, maybe not yet authenticated).
     */
    val connected: Boolean,
    /**
     * Authenticated: commands and the device list work.
     */
    val ready: Boolean,
    /**
     * Our session id (the NOTIFY `origin` of our own writes), 0 = unknown.
     */
    val session: Long,
    /**
     * `viewer`, `control` or `admin`.
     */
    val role: String,
    /**
     * Commands this role may not send (`policy.denied`).
     */
    val denied: List<LinkDenied>,
    /**
     * The session ended (see `close_code` / `close_reason`).
     */
    val closed: Boolean,
    /**
     * The hub's close code, -1 = none.
     */
    val closeCode: Int,
    /**
     * The hub's close reason.
     */
    val closeReason: String,
    /**
     * What to tell the user (WP C15).
     */
    val phase: LinkPhase,
    /**
     * [`LinkPhase::Reconnecting`]: failed tries since the session was lost.
     */
    val reconnectAttempt: Long,
    /**
     * [`LinkPhase::Reconnecting`]: ms until the next try, 0 = now.
     */
    val reconnectInMs: Long,
    /**
     * `window` or `fixed`, for [`LinkPhase::NeedsPairing`]'s wording; "" with
     * no session.
     */
    val pinSource: String,
    /**
     * The hub refused or revoked the stored token, during a reconnect too:
     * forget it. Cleared by the next pairing.
     */
    val tokenRefused: Boolean,
)

/**
 * `GET /dspi/v1/info` (spec 3.2), for a hub added by address.
 */
data class LinkInfo(
    /**
     * Lowercase UUID, stable per hub installation.
     */
    val hubId: String,
    /**
     * The hub's display name.
     */
    val hubName: String,
    /**
     * `console` or `bridge`.
     */
    val hubKind: String,
    /**
     * `none` or `pin`.
     */
    val auth: String,
    /**
     * The Link protocol minor version it speaks.
     */
    val protoMinor: Long,
    /**
     * WebSocket path (`/dspi/v1` by default).
     */
    val wsPath: String,
    /**
     * Serials of the devices it shares.
     */
    val serials: List<String>,
)

/**
 * A typed hub address (spec 3.3).
 */
data class LinkAddress(
    /**
     * Host name or IP address.
     */
    val host: String,
    /**
     * TCP port.
     */
    val port: Int,
)

/**
 * The extension channel (Bofr5555/DSPi fork; `REQ_EXTENSION` 0x00), as
 * probed on connect (WP S3) and read on demand (WP C8).
 */
data class ExtStatus(
    /**
     * `EXT_LIST`: supported sub-command ids; empty on stock firmware.
     */
    val supported: List<Int>,
    /**
     * Whether `EXT_CROSSFEED_PAIR_MAP` is usable: listed by `EXT_LIST` and
     * read successfully on connect.
     */
    val hasPairMap: Boolean,
    /**
     * Whether `EXT_CORE_VREG` is usable: listed by `EXT_LIST` and read
     * successfully on connect.
     */
    val hasCoreVreg: Boolean,
)

/**
 * `EXT_CORE_VREG` status (16 bytes, `dspi_proto::ext::CoreVregStatus`).
 */
data class CoreVregInfo(
    /**
     * Live VREG code; `millivolts` is its voltage (0 if unknown).
     */
    val liveVreg: Int,
    /**
     * Core voltage, mV; 0 if unknown.
     */
    val millivolts: Int,
    /**
     * The persisted selection in the flash directory; 0 = build default.
     */
    val storedSel: Int,
    /**
     * The build's default VREG code.
     */
    val defaultVreg: Int,
    /**
     * The stored selection was raised by the firmware.
     */
    val autoRaised: Boolean,
    /**
     * The user opted out of automatic escalation
     * (`CORE_VREG_FLAG_AUTO_DISABLED`).
     */
    val autoDisabled: Boolean,
    /**
     * Own-watchdog hangs this power session, not yet acted on.
     */
    val hangCount: Int,
    /**
     * A voltage trial is running.
     */
    val trialActive: Boolean,
    /**
     * The trial's VREG code, valid while `trial_active`.
     */
    val trialVreg: Int,
    /**
     * VREG code of the trial whose run ended in a hang; 0 = none.
     */
    val failedTrialVreg: Int,
    /**
     * How long that trial survived, s.
     */
    val failedTrialUptimeS: Long,
    /**
     * This run's uptime, s.
     */
    val uptimeS: Long,
)

/**
 * `REQ_OUTPUT_LATENCY` status (config.h; 12 bytes). Field meanings as in
 * the firmware's `OutputLatencyStatus`.
 */
data class OutputLatency(
    /**
     * The raw 12-byte reply, for fields this build does not name yet.
     */
    val raw: List<Int>,
    /**
     * Decoded `(name, value)` pairs, in the firmware's order.
     */
    val fields: List<NamedValue>,
)

/**
 * `REQ_GET_CLOCK_DIAG` (0x82): empty unless the firmware was built with
 * `DSPI_CLOCK_DIAG`.
 */
data class ClockDiag(
    /**
     * The firmware was built with `DSPI_CLOCK_DIAG`.
     */
    val available: Boolean,
    /**
     * The raw reply.
     */
    val raw: List<Int>,
    /**
     * Decoded `(name, value)` pairs, in the firmware's order.
     */
    val fields: List<NamedValue>,
)

/**
 * A decoded diagnostic value.
 */
data class NamedValue(
    /**
     * The value's name.
     */
    val name: String,
    /**
     * The value, as text.
     */
    val value: String,
)

/**
 * What a `.uf2` file is (WP C11): checked before anything is flashed.
 */
data class Uf2Info(
    /**
     * Whether the file is a well-formed UF2 for an RP2040 or RP2350.
     */
    val valid: Boolean,
    /**
     * Why not, when `valid` is false.
     */
    val problem: String,
    /**
     * UF2 family id (`0xE48BFF56` RP2040, `0xE48BFF59` RP2350 ARM-S, ...).
     */
    val familyId: Long,
    /**
     * 0 RP2040, 1 RP2350, -1 unknown.
     */
    val platform: Int,
    /**
     * UF2 blocks in the file.
     */
    val numBlocks: Long,
    /**
     * Bytes of flash the image covers.
     */
    val payloadBytes: Long,
    /**
     * The DSPi firmware version found in the image (`1.1.6`), "" if none.
     * It is the image's program-version string, so an untagged build
     * carries a `git describe` suffix (`1.1.6-beta3-16-g557bce7`); compare
     * versions on the leading `major.minor.patch[-betaN]` only.
     */
    val firmwareVersion: String,
)

/**
 * A mounted RP2040/RP2350 bootloader drive (`RPI-RP2` / `RP2350`).
 */
data class BootloaderDrive(
    /**
     * Mount point or drive root.
     */
    val path: String,
    /**
     * 0 RP2040, 1 RP2350, -1 unknown (from `INFO_UF2.TXT`).
     */
    val platform: Int,
    /**
     * `INFO_UF2.TXT`, verbatim.
     */
    val info: String,
)

/**
 * One output-latency option (`OutputLatencyOptionWire`, config.h; 8
 * bytes), from `fetch_output_latency_options` (WP C8).
 */
data class OutputLatencyOption(
    /**
     * `OutputLatencyId`, the value `set_output_latency` takes (never 0).
     */
    val id: Int,
    /**
     * `OUTPUT_LATENCY_FLAG_STREAM_ONLY`: runs only with a streamed input
     * (S/PDIF, I2S, ADAT); USB input runs the fallback instead.
     */
    val streamOnly: Boolean,
    /**
     * `OUTPUT_LATENCY_WIRE_AVAILABLE`: runs as itself on the active source.
     */
    val available: Boolean,
    /**
     * Nominal ring fill target, µs.
     */
    val latencyUs: Int,
    /**
     * Nominal stream-input batch, µs.
     */
    val batchUs: Int,
    /**
     * What choosing it gives now (active source and rate applied), µs.
     */
    val effectiveUs: Int,
)

/**
 * The output rings' counters and watermarks (`fetch_ring_health`). The
 * underrun, refused and over-budget counts are cumulative; the rest clear on
 * `reset_buffer_stats`.
 */
data class RingHealth(
    /**
     * How full the rings are kept, frames (Fill Target).
     */
    val targetFrames: Int,
    /**
     * The same as a time, µs.
     */
    val targetUs: Int,
    /**
     * Frames a stream input delivers per call; the fill swings by about this.
     */
    val batchFrames: Int,
    /**
     * Times the outputs ran dry while a source owed audio. A host that pauses
     * its stream does not count.
     */
    val underrunEpisodes: Long,
    /**
     * Audio blocks dropped because the rings had no room.
     */
    val refusedBlocks: Long,
    /**
     * The emptiest a ring got just before a write, frames; none before the
     * first write.
     */
    val lowestFill: Long?,
    /**
     * Longest wait between input deliveries, µs.
     */
    val worstInputGapUs: Long,
    /**
     * Longest gap between audio-carrying USB packets, µs.
     */
    val worstUsbGapUs: Long,
    /**
     * Background steps that overran their main-loop budget.
     */
    val overBudgetSteps: Long,
)

/**
 * One output's fill, scaled and judged (`fetch_output_fills`).
 */
data class OutputFill(
    /**
     * Fill to frame resolution, %: of the ring where the firmware has the
     * latency setting (at most 100), else of the firmware's fixed scale (which
     * can pass 100).
     */
    val fillPct: Double,
    /**
     * Lowest fill since the last reset, % on the same scale.
     */
    val minPct: Int,
    /**
     * Highest fill since the last reset, % on the same scale.
     */
    val maxPct: Int,
    /**
     * The band of `fill_pct`, around the live latency target where there is
     * one.
     */
    val band: FillBand,
)

/**
 * One sample of the Stats window's fast poll (`fetch_stats_tick`).
 */
data class StatsTick(
    /**
     * The buffer fill levels and their watermarks.
     */
    val buffers: BufferStats,
    /**
     * The live outputs' fill, from the same read. `None` when the fill target
     * could not be read: keep the last fills.
     */
    val fills: List<OutputFill>?,
)

/**
 * Who chose the analyser configuration the device holds
 * (`rta_get_ownership`). The last console to push one drives it, and every
 * other console follows.
 */
data class RtaOwnership(
    /**
     * False: the device holds what this console asked for, and the fields
     * below are 0. True: someone else's configuration.
     */
    val following: Boolean,
    /**
     * The session that pushed it; 0 when the writer is unknown.
     */
    val origin: Int,
    /**
     * The device's tap, `RTA_TAP_INPUT` or `RTA_TAP_OUTPUT`.
     */
    val tap: Int,
    /**
     * The device's channels.
     */
    val mask: Int,
    /**
     * The device's transform size.
     */
    val fftOrder: Int,
)

/**
 * One GET the host is asked to make.
 */
data class AutoEqFetchRequest(
    /**
     * The URL, already percent-encoded.
     */
    val url: String,
    /**
     * The `Accept` header to send, if any.
     */
    val accept: String?,
    /**
     * The `User-Agent` header to send. GitHub refuses a request without one.
     */
    val userAgent: String,
)

/**
 * What the server answered, whatever the status: a 403 or a 500 is an answer.
 */
data class AutoEqFetchResponse(
    /**
     * The HTTP status, after following redirects.
     */
    val status: Int,
    /**
     * The body, as received. Pass it for an error status too.
     */
    val body: List<Int>,
    /**
     * The `Retry-After` header in seconds; `None` if absent or a date.
     */
    val retryAfterS: Long?,
    /**
     * The `X-RateLimit-Remaining` header.
     */
    val rateLimitRemaining: Long?,
    /**
     * The `X-RateLimit-Reset` header, in Unix seconds.
     */
    val rateLimitReset: Long?,
)

/**
 * What the "Update Database" dialog shows about the database in place.
 */
data class AutoEqDatabaseInfo(
    /**
     * A user database is at `db_path`, which is what decides whether "Reset to
     * Built-in" is offered. True for a damaged file too, so it can be reset.
     */
    val hasUserDatabase: Boolean,
    /**
     * Why the file could not be read; `None` if it could, or there is none.
     */
    val problem: String?,
    /**
     * The file's format version; 0 with no readable database.
     */
    val version: Int,
    /**
     * When it was generated, ISO 8601 as the file has it; empty if unknown. An
     * imported file can say anything here: show it as text if it does not parse.
     */
    val generatedAt: String,
    /**
     * Profiles it holds.
     */
    val entryCount: Long,
)

/**
 * Where a rebuild has got to, from [`AutoEqRebuild::poll`].
 */
data class AutoEqRebuildProgress(
    /**
     * 0.0 to 1.0.
     */
    val fraction: Float,
    /**
     * A line for the progress dialog; once finished, the result in words.
     */
    val status: String,
    /**
     * The rebuild is over, one way or the other; the fields below are final.
     */
    val finished: Boolean,
    /**
     * The database was written. It may still have parts missing: see
     * `failed_profiles` and `failed_listings`. On a failure the file was left
     * as it was.
     */
    val succeeded: Boolean,
    /**
     * Once finished without success, why: `cancelled`, or an
     * [`AutoEq`](DspiError::AutoEq) code; empty otherwise.
     */
    val code: String,
    /**
     * With `code` `rate_limited`: seconds until it is worth trying again, when
     * the server said.
     */
    val retryAfterS: Long?,
    /**
     * Profiles in the database written.
     */
    val entries: Long,
    /**
     * Profiles that should have come and did not. Tell the person.
     */
    val failedProfiles: Long,
    /**
     * Directory listings that failed, whose profiles were never seen. Tell the
     * person.
     */
    val failedListings: Long,
    /**
     * Folders with no usable profile, which is normal upstream.
     */
    val skippedProfiles: Long,
)

/**
 * What a board needs, read before it enters the bootloader. The default is
 * the safe one: unknown.
 */
data class FirmwareGuardBoard(
    /**
     * The lowest core voltage this board may be left on, in mV. 1150: not at
     * risk. Above that: at risk. Anything else, 0 included: unknown.
     */
    val requiredMv: Int,
    /**
     * Where it came from.
     */
    val source: FirmwareGuardBoardSource,
)

/**
 * The result of [`firmware_guard_check`]. The default blocks.
 */
data class FirmwareGuardVerdict(
    /**
     * True only for `Clear` and `Confirmed`. Anything else must not flash.
     */
    val allowed: Boolean,
    /**
     * The decision.
     */
    val decision: FirmwareGuardDecision,
    /**
     * Why.
     */
    val reason: FirmwareGuardReason,
    /**
     * For the user, in English.
     */
    val message: String,
    /**
     * What to ask the user to type when a risk is involved, else "": the
     * phrase, or for [`FirmwareGuardReason::Overvolt`] the word. Compared
     * exactly: case and spaces count, and the one does not stand for the other.
     */
    val confirmationPhrase: String,
    /**
     * The image's stamped voltage in mV; 0 if it has none (taken as 1150).
     */
    val imageMv: Int,
    /**
     * The board record's `required_mv`, as given.
     */
    val requiredMv: Int,
)

/**
 * What to tell the user about a [`LinkPhase`].
 */
data class LinkPhaseText(
    /**
     * Stable key of `text`, for localising: `no_device`, `needs_pairing.fixed`.
     */
    val key: String,
    /**
     * The phase's name ([`link_phase_key`]), also for an entry split by
     * `pin_source`.
     */
    val phase: String,
    /**
     * The English.
     */
    val text: String,
    /**
     * Stable key of `action`, if the phase has a button of its own.
     */
    val actionKey: String?,
    /**
     * The English of that button.
     * [`LinkPhase::Reconnecting`] has one, which calls `link_close`: the owner's
     * rule is that a lost connection always offers the way out.
     */
    val action: String?,
)

/**
 * One notification as the tap saw it (WP CG23).
 */
data class RawNotification(
    /**
     * The packet in the firmware's v2 layout (`notify.h`), or the 8-byte v1
     * volume packet. Rebuilt from the decoded event, with the flags and the
     * padding zero as the firmware sends them: byte for byte what the
     * device sent for every event this build knows. A packet the reader
     * could not decode is kept as it came.
     */
    val packet: List<Int>,
    /**
     * The link's attribution: the DSPi Link session id of the writer, 0
     * for the device itself; `None` over USB and MIDI.
     */
    val origin: Int?,
    /**
     * The echo filter's verdict: the echo of a write of this core's own.
     * Only a `PARAM_CHANGED` or a `BULK_INVALIDATED` can be one; every
     * other event is `false`.
     */
    val own: Boolean,
    /**
     * Something before this entry is missing: the tap's ring overflowed,
     * or the reader saw a gap in the device's sequence numbers.
     */
    val lost: Boolean,
    /**
     * When the reader received it, ms since the Unix epoch.
     */
    val receivedMs: Long,
)

/**
 * A voltage the flow offers on the connected device.
 */
data class VregChoice(
    /**
     * VREG code.
     */
    val code: Int,
    /**
     * The voltage, mV.
     */
    val millivolts: Int,
    /**
     * A trial of it would raise this unit above 1.20 V now, so `OVERVOLT`
     * must be typed.
     */
    val needsWord: Boolean,
    /**
     * The same for a save (`core_vreg_manual_set`), which does not count a
     * running trial as current.
     */
    val saveNeedsWord: Boolean,
)

/**
 * The flow as a client shows it.
 */
data class VregCalView(
    /**
     * The connection can use the flow: `EXT_CORE_VREG` present, writable,
     * and not refused by a hub. While false with phase `Idle`, hide the
     * flow. While false in another phase the device is away: show the phase.
     */
    val available: Boolean,
    /**
     * Where the flow is.
     */
    val phase: VregCalPhase,
    /**
     * A stable key for `message`, for clients that localise.
     */
    val messageKey: String,
    /**
     * The state or result, stated plainly in English.
     */
    val message: String,
    /**
     * The warning to show before the flow, with the datasheet limits.
     */
    val warning: String,
    /**
     * What a soak does and does not show.
     */
    val soakNote: String,
    /**
     * The voltages offered, lowest first. Empty on a build default the flow
     * does not cover, or before a first status.
     */
    val choices: List<VregChoice>,
    /**
     * What to type when `needs_word` or `commit_needs_word`: `OVERVOLT`,
     * exactly.
     */
    val confirmationWord: String,
    /**
     * `core_vreg_cal_commit` needs the word now, while `phase` is `Passed`.
     * Saving a trial above 1.20 V that is not already stored asks for it, even
     * though it was typed to start the trial: going from RAM to flash is an
     * upward change of its own. Ask again; do not reuse the earlier answer.
     */
    val commitNeedsWord: Boolean,
    /**
     * `core_vreg_manual_set(0, ..)`, the reset to the build default, needs the
     * word now: the unit's current voltage cannot be read from the last
     * status, so nobody can say the reset does not raise it (WP QD28b).
     */
    val resetNeedsWord: Boolean,
    /**
     * The soak to suggest, seconds.
     */
    val defaultSoakS: Long,
    /**
     * The shortest soak accepted, seconds.
     */
    val minSoakS: Long,
    /**
     * The run's or found trial's voltage; 0 if none.
     */
    val targetVreg: Int,
    /**
     * The soak asked for, seconds; 0 if none.
     */
    val soakS: Long,
    /**
     * Seconds of soak counted so far.
     */
    val elapsedS: Long,
    /**
     * The failure shown or on record: its voltage; 0 if none.
     */
    val failedVreg: Int,
    /**
     * Seconds the failed trial ran, if this host saw it start and the record
     * still has the time.
     */
    val ranS: Long?,
    /**
     * The device's uptime when that trial hung; 0 if the record lost it. Its
     * whole run, so at most an upper bound on the trial.
     */
    val uptimeAtHangS: Long,
    /**
     * The next voltage up to offer after that failure; 0 if none.
     */
    val nextVreg: Int,
    /**
     * Nothing above that failure to try: a hardware problem.
     */
    val hardwareProblem: Boolean,
    /**
     * Why the result is unknown (`record_gone`, `not_started`,
     * `trial_changed`); `None` unless `phase` is `Unknown`.
     */
    val unknownReason: String?,
    /**
     * The device stopped answering since the last status: a hang in
     * progress, or a dropped link. The result is still open.
     */
    val linkLost: Boolean,
    /**
     * `core_vreg_cal_start` applies now.
     */
    val canStart: Boolean,
    /**
     * `core_vreg_cal_keep` applies now.
     */
    val canKeep: Boolean,
    /**
     * `core_vreg_cal_commit` applies now.
     */
    val canCommit: Boolean,
    /**
     * The last status read from the device.
     */
    val status: CoreVregInfo?,
    /**
     * Why the last call or read failed, in a sentence; `None` once one
     * succeeded.
     */
    val lastError: String?,
)

/**
 * Where a DSPi Link session stands, for the UI's wording
 * ([`LinkStatus::phase`]).
 */
enum class LinkPhase {
    /**
     * No session.
     */
    IDLE,
    /**
     * The hub wants a PIN (never paired, or the token was refused or revoked:
     * see `token_refused`): ask for it and call `link_pair`. Retries stop here.
     */
    NEEDS_PAIRING,
    /**
     * Connected and authenticated, but the hub has no DSPi to offer: the
     * board is off, or its control interface is not enabled. Not a failure
     * of the hub or the pairing ("Connected to hub, no DSPi found"). The
     * core binds the device by itself when it comes back.
     */
    NO_DEVICE,
    /**
     * A DSPi is available and none is bound: `link_devices`, then
     * `link_select_device`.
     */
    CHOOSE_DEVICE,
    /**
     * Bound to a device.
     */
    BOUND,
    /**
     * The session was lost, or the bound device is being re-attached; the
     * core retries with backoff. Entered at once. `close_reason` says why,
     * `reconnect_attempt` and `reconnect_in_ms` how it goes; `link_close`
     * stops it. The mirror stays last known; calls that need the device fail
     * at once with `Disconnected`, and nothing is queued.
     */
    RECONNECTING,
    /**
     * Ended and not retried: see `close_code` and `close_reason`. A protocol
     * error is final, also when it comes from a redial (a hub of another
     * protocol version answers).
     */
    CLOSED,
    /**
     * The hub refuses this client (a 4xx handshake). Retrying will not help
     * until something changes on the hub: see `close_reason`.
     */
    REFUSED,
}

/**
 * How an output's fill reads ([`OutputFill::band`]). The Console shows these
 * green, yellow and red.
 */
enum class FillBand {
    /**
     * Within the expected swing.
     */
    GOOD,
    /**
     * Outside the expected swing.
     */
    WARN,
    /**
     * Empty, or too full to take a write.
     */
    BAD,
}

/**
 * Where a [`FirmwareGuardBoard`]'s voltage came from.
 */
enum class FirmwareGuardBoardSource {
    /**
     * No device was open.
     */
    NO_DEVICE,
    /**
     * The board is in the bootloader, where it cannot be asked.
     */
    BOOTLOADER,
    /**
     * The device was open, but gave no answer that can be believed.
     */
    READ_FAILED,
    /**
     * `EXT_CORE_VREG`.
     */
    EXT_CORE_VREG,
    /**
     * The status block's live voltage, on firmware without `core_vreg`.
     */
    STATUS_BLOCK,
}

/**
 * The guard's answer. Flash only on [`FirmwareGuardVerdict::allowed`].
 */
enum class FirmwareGuardDecision {
    /**
     * The image is not firmware. Confirmation does not help.
     */
    REFUSED,
    /**
     * Blocked until the phrase is typed.
     */
    NEEDS_CONFIRMATION,
    /**
     * There was a risk, and the phrase was typed.
     */
    CONFIRMED,
    /**
     * No known risk.
     */
    CLEAR,
}

/**
 * Why, as a stable key for clients that localise the message.
 */
enum class FirmwareGuardReason {
    /**
     * The image failed the UF2 check.
     */
    IMAGE_INVALID,
    /**
     * No known risk.
     */
    NO_RISK,
    /**
     * At-risk board; the image does not say what voltage it runs at.
     */
    IMAGE_UNKNOWN,
    /**
     * At-risk board; the image is stamped below what the board needs.
     */
    IMAGE_LOWER,
    /**
     * The board's needs are not known.
     */
    BOARD_UNKNOWN,
    /**
     * WP CG14: the image runs above 1.20 V and above the board's current
     * voltage. Its `confirmation_phrase` is the word `OVERVOLT`.
     */
    OVERVOLT,
}

/**
 * Where a run is: [`VregCalView::phase`]. The details are in the view.
 */
enum class VregCalPhase {
    /**
     * The flow is not open.
     */
    IDLE,
    /**
     * Open: show the warning and what the device has on record.
     */
    REVIEW,
    /**
     * Clearing the device's record before the trial.
     */
    CLEARING,
    /**
     * The trial was sent and is not seen running yet.
     */
    STARTING_TRIAL,
    /**
     * The trial runs; the soak is counting. Abort is available.
     */
    SOAKING,
    /**
     * Passed: the trial still runs and nothing is saved. Commit or end.
     */
    PASSED,
    /**
     * The trial hung: `failed_vreg`, `ran_s`, `next_vreg`, `hardware_problem`.
     */
    FAILED,
    /**
     * The result cannot be known: run again.
     */
    UNKNOWN,
    /**
     * A trial nobody here started is running: end or keep.
     */
    TRIAL_FOUND,
    /**
     * A kept trial outside the flow's range: left alone, cannot pass.
     */
    TRIAL_LEFT_RUNNING,
    /**
     * Ending the trial.
     */
    ENDING,
    /**
     * The trial ended.
     */
    ENDED,
    /**
     * Saving: waiting to read the voltage back.
     */
    COMMITTING,
    /**
     * Saved and read back.
     */
    COMMITTED,
    /**
     * A save or an end did not show in time. Nothing was retried.
     */
    VERIFY_FAILED,
}

/**
 * What can happen to the demo device: [`DspiCore::core_vreg_demo_event`].
 */
enum class VregDemoEvent {
    /**
     * The watchdog fires.
     */
    HANG,
    /**
     * A requested reboot: no failure on record.
     */
    REBOOT,
    /**
     * Power lost: every record gone.
     */
    POWER_CYCLE,
    /**
     * `seconds` pass on the device's clock.
     */
    ADVANCE_UPTIME,
}

/**
 * A rebuild running on the core's threads. Poll it from a UI timer; dropping it
 * cancels it, without waiting for the requests in flight.
 */
interface AutoEqRebuild : AutoCloseable {
    /**
     * The newest progress. Does not block.
     */
    fun poll(): AutoEqRebuildProgress
    /**
     * Stop at the next batch of profiles; nothing is written. Does not block:
     * keep polling until `finished`.
     */
    fun cancel()
}
